moduleHumanResourceComment: "Zarządzanie zasobami ludzkimi&#44 w tym urlopami i kompetencjami",
moduleImputation: "Rejestrowanie czasu",
moduleImputationComment: "Ewidencja czasu w korelacji z harmonogramem umożliwia rejestrowanie czasu poświęconego na każdą aktywność przez każdy zasób.",
moduleIncomes: "Przychody",
moduleIncomesComment: "Zarządzanie przychodami śledzi aktywność projektową jako centra zysków.",
moduleLocalization: "Zlecenia tłumaczeń",
moduleLocalizationComment: "Zarządzanie zleceniami tłumaczeń umożliwia zlecanie tłumaczeń tekstów tłumaczom zgodnie z ich kompetencjami językowymi. <br/>Powiązane z zarządzaniem konfiguracją pozwala łatwo identyfikować języki do przetłumaczenia według języków wersji produktu lub komponentu.",
moduleMail: "Poczta",
moduleMailComment: "Moduł poczty do śledzenia korespondencji fizycznej lub elektronicznej wysyłanej i otrzymywanej",
moduleMeeting: "Spotkania",
moduleMeetingComment: "Zarządzanie spotkaniami pozwala śledzić różne spotkania projektowe i umieszczać je w harmonogramie.",
moduleNotification: "Powiadomienia",
moduleNotificationComment: "System powiadomień może generować alerty.",
moduleOrganization: "Organizacje",
moduleOrganizationComment: "Zarządzanie organizacjami zapewnia przekrojową konsolidację danych z wielu projektów.",
modulePlanning: "Planowanie",
modulePlanningComment: "Zarządzanie planowaniem pozwala wyliczyć „capacity planning” aktywności z uwzględnieniem dostępności zasobów pracujących równolegle w wielu projektach.",
modulePoker: "Planning poker",
modulePokerComment: "Planning poker implementuje zwinne podejście (Scrum poker) – technikę konsensusowego&#44 ugrywalnionego szacowania wysiłku lub względnej wielkości celów rozwojowych.<br/> Członkowie zespołu szacują poprzez zagrywanie zakrytych kart z wartościami zamiast wypowiadania liczb na głos.<br/> Po odsłonięciu kart następuje dyskusja i doprecyzowanie estymacji.",
moduleProjectAnalysis: "Analiza projektu",
moduleProjectAnalysisComment: "Moduł umożliwia tworzenie&#44 monitorowanie i realizację planów działań w oparciu o założenia&#44 ograniczenia i wnioski z doświadczeń dla projektu.",
moduleRequirement: "Wymagania",
moduleRequirementComment: "Zarządzanie wymaganiami rejestruje zobowiązania funkcjonalne&#44 techniczne i kontraktowe.",
moduleReview: "Nadzór",
moduleReviewComment: "Zarządzanie elementami nadzoru umożliwia śledzenie decyzji wpływających na projekt&#44 pytań/odpowiedzi&#44 wejść i produktów dostarczalnych.",
moduleRisk: "Ryzyka",
moduleRiskComment: "Plan zarządzania ryzykiem pozwala przewidywać potencjalne ryzyka projektu.",
moduleScreenExplanation: "Twoja instancja jest gotowa.<br>Możesz teraz wybrać moduły do aktywacji lub wyłączenia.<br/>Wrócisz do tego ekranu później&#44 aby zmienić wybór.<br/>Kliknij Zapisz po zakończeniu selekcji.",
moduleSituation: "Sytuacje finansowe",
moduleSituationComment: "Zarządzanie historią każdego elementu finansowego",
moduleSkillManagement: "Zarządzanie kompetencjami",
moduleSkillManagementComment: "Zarządzanie kompetencjami pozwala definiować kompetencje w strukturze hierarchicznej oraz ich możliwe poziomy.<br/> Następnie możesz określić kompetencje każdego zasobu.<br/> Dedykowany ekran pomaga w alokacji zasobów do projektów – wyszukuje zasób o danej kompetencji i pokazuje jego dostępność w zadanym okresie.<br/> Można też wskazać kompetencje wymagane dla aktywności i uzyskać pomoc w doborze najbardziej odpowiedniego zasobu przy przydziale.",
moduleTargetMilestone: "Docelowy kamień milowy",
moduleTargetMilestoneComment: "Zarządzaj docelowymi kamieniami milowymi dla elementów nienadających się do planowania (wymagania&#44 zgłoszenia&#44 wersje produktu&#44 wejścia&#44 dostarczalne&#44 dostawy)",
moduleTechnical: "Techniczne",
moduleTechnicalProgress: "Postęp techniczny",
moduleTechnicalProgressComment: "Umożliwia śledzenie postępu technicznego aktywności w jednostkach liczbowych&#44 niezwiązanych bezpośrednio z postępem obciążenia pracą",
moduleTicket: "Ticketing",
moduleTicketComment: "Zarządzanie zgłoszeniami umożliwia śledzenie nieplanowanych zdarzeń (incydentów&#44 niezgodności&#44 wniosków o zmianę itp.).",
moduleTimeTracking: "Rejestrowanie czasu",
moduleTodoList: "Lista zadań (To-Do)",
moduleTodoListComment: "Moduł dodaje listy zadań do aktywności&#44 zgłoszeń i działań&#44 by doprecyzować co trzeba zrobić bez tworzenia nowych elementów (podaktywności)",
moduleTokenManagement: "Tokeny przy zgłoszeniach",
moduleTokenManagementComment: "Zarządzanie tokenami realizowanymi na zgłoszeniach&#44 pozwala zdefiniować pulę tokenów zamówioną przez klienta i wykorzystanie tej puli.",
moduleVoting: "Głosowanie",
moduleVotingComment: "Głosowanie dla zgłoszeń&#44 aktywności i wymagań<br/> Moduł pozwala priorytetyzować elementy w sposób kolaboracyjny<br> Administrator definiuje zasady przydziału punktów głosowania i zasady ich wykorzystania. Użytkownicy przydzielają punkty do elementów&#44 faworyzując najpopularniejsze.",
