startGuideActivity: "Aktywności to zadania planowane w projektach. <br/>Możesz tworzyć strukturę podziału pracy swoich projektów. <br/>Nie ma ograniczeń poziomów tej struktury (fazy / podfazy / zadania / podzadania ...).",
startGuideAffectation: "Aby widzieć elementy projektu&#44; zasób musi być do niego zaalokowany.<br/>Alokacja do projektu automatycznie daje widoczność na elementy jego podprojektów.",
startGuideClient: "Klienci to podmioty&#44; dla których pracujesz.<br/>Mogą być wewnętrzni lub zewnętrzni względem organizacji.",
startGuideContact: "Kontakty to osoby&#44; z którymi utrzymujesz kontakt po stronie klienta.",
startGuideFooter: "To najważniejsze funkcje. <br/>Gdy się z nimi oswoisz&#44; odkryjesz (liczne) inne moduły wspierające zarządzanie projektami.",
startGuideImputation: "Zasoby wpisują pracę rzeczywistą na ekranie Karta pracy dzień po dniu i aktywność po aktywności.<br/> Ponowna estymacja pracy « pozostałej » aktualizuje plan z rzeczywistym postępem.",
startGuideIntro: "Krótki samouczek ułatwiający pierwsze kroki z ProjeQtOr.<br/> Wykonaj te kroki&#44; aby skonfigurować pierwsze elementy.<br/> Naciśnij [F1]&#44; aby przejść do podręcznika użytkownika z dodatkowymi informacjami.<br/> Wróć do menu &#34Start guide&#34&#44; aby trafić tu ponownie.",
startGuideMilestone: "Kamienie milowe to kluczowe daty projektu.<br/>Mogą definiować wejścia (kamienie stałe) lub dostarczalności (kamienie pływające).",
startGuidePlanning: "Planowanie prezentowane jest w widoku Gantta.<br/>Aby planować&#44; przypisz zasoby do aktywności i określ pracę do wykonania (planowanie jest sterowane pracą).<br/>Następnie zdefiniuj zależności między zadaniami i kamieniami...<br/>Możesz uruchomić kalkulację planu z uwzględnieniem ograniczeń dostępności zasobów.",
startGuideProject: "Projekt to podstawowy element ProjeQtOr.<br/>Każdy element jest powiązany z projektem.<br/>Prawa dostępu również definiowane są na poziomie projektu.",
startGuideResource: "Zasoby to osoby lub maszyny&#44; które będą pracować nad zadaniami.<br/>Jeśli zaznaczysz « jest użytkownikiem »&#44; zasób (osoba) będzie mógł logować się do ProjeQtOr.",
startGuideTicket: "Zgłoszenia pozwalają śledzić każde incydentalne zdarzenie związane z projektem&#44; takie jak błędy lub dowolne żądania.<br/>W razie potrzeby można je łatwo kopiować do aktywności bez ponownego wprowadzania danych&#44; zachowując powiązanie z pierwotnym wnioskiem.",
